#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <c10/cuda/CUDAGuard.h>

#include <cute/tensor.hpp>

using namespace cute;

// Supported fast path: groups=1, stride=1, dilation=1, output_padding=0, K=3.
// For ConvTranspose3d with stride=1/dilation=1:
//   y[n,o,od,oh,ow] = bias[o] + sum_i sum_{rd,rh,rw}
//       x[n,i,od+padding-rd, oh+padding-rh, ow+padding-rw] * w[i,o,rd,rh,rw]
// with out-of-range x treated as zero.

template <typename T>
__global__ void conv_transpose3d_s1_k3_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int Cin, int Cout,
    int Din, int Hin, int Win,
    int Do, int Ho, int Wo,
    int padding,
    int tiles_d, int tiles_h, int tiles_w)
{
  constexpr int K = 3;
  constexpr int KR = K * K * K;      // 27
  constexpr int TD = 8;
  constexpr int TH = 8;
  constexpr int TW = 8;
  constexpr int HD = TD + K - 1;     // 10
  constexpr int HH = TH + K - 1;     // 10
  constexpr int HW = TW + K - 1;     // 10
  constexpr int IC_CHUNK = 8;
  constexpr int OC_BLOCK = 8;
  constexpr int THREADS = 512;
  constexpr int SP_TILE = TD * TH * TW;       // 512
  constexpr int LANES = THREADS / OC_BLOCK;   // 64
  constexpr int J = SP_TILE / LANES;          // 8

  const int tid = threadIdx.x;
  const int n = blockIdx.z;
  const int oc0 = blockIdx.y * OC_BLOCK;

  const int t = blockIdx.x;
  const int tw = t % tiles_w;
  const int rem0 = t / tiles_w;
  const int th = rem0 % tiles_h;
  const int td = rem0 / tiles_h;

  const int od0 = td * TD;
  const int oh0 = th * TH;
  const int ow0 = tw * TW;

  const int64_t sXn = (int64_t)Cin * Din * Hin * Win;
  const int64_t sXc = (int64_t)Din * Hin * Win;
  const int64_t sXd = (int64_t)Hin * Win;
  const int64_t sXh = (int64_t)Win;

  const int64_t sYn = (int64_t)Cout * Do * Ho * Wo;
  const int64_t sYc = (int64_t)Do * Ho * Wo;
  const int64_t sYd = (int64_t)Ho * Wo;
  const int64_t sYh = (int64_t)Wo;

  const int64_t sWi = (int64_t)Cout * KR;
  const int64_t sWo = (int64_t)KR;
  const int64_t sWd = (int64_t)K * K;
  const int64_t sWh = (int64_t)K;

  Tensor mX = make_tensor(
      make_gmem_ptr(X),
      make_shape(N, Cin, Din, Hin, Win),
      make_stride(sXn, sXc, sXd, sXh, Int<1>{})
  );

  Tensor mY = make_tensor(
      make_gmem_ptr(Y),
      make_shape(N, Cout, Do, Ho, Wo),
      make_stride(sYn, sYc, sYd, sYh, Int<1>{})
  );

  Tensor mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Cin, Cout, Int<K>{}, Int<K>{}, Int<K>{}),
      make_stride(sWi, sWo, sWd, sWh, Int<1>{})
  );

  Tensor mB = make_tensor(
      make_gmem_ptr(B),
      make_shape(Cout),
      make_stride(Int<1>{})
  );

  __shared__ T sX_raw[IC_CHUNK * HD * HH * HW];
  __shared__ T sW_raw[OC_BLOCK * IC_CHUNK * KR];

  Tensor sX = make_tensor(
      make_smem_ptr(sX_raw),
      make_shape(Int<IC_CHUNK>{}, Int<HD>{}, Int<HH>{}, Int<HW>{}),
      make_stride(Int<HD * HH * HW>{}, Int<HH * HW>{}, Int<HW>{}, Int<1>{})
  );

  Tensor sW = make_tensor(
      make_smem_ptr(sW_raw),
      make_shape(Int<OC_BLOCK>{}, Int<IC_CHUNK>{}, Int<KR>{}),
      make_stride(Int<IC_CHUNK * KR>{}, Int<KR>{}, Int<1>{})
  );

  const int lane = tid & (LANES - 1);  // 0..63: keep one output channel per warp for coalesced stores
  const int oc = tid / LANES;          // 0..7: 64 spatial lanes share the same output channel
  const int ocg = oc0 + oc;
  const bool oc_valid = (ocg < Cout);

  int gd[J], gh[J], gw[J];
  int ld[J], lh[J], lw[J];
  bool valid[J];

  const float bval = (B != nullptr && oc_valid) ? (float)mB(ocg) : 0.0f;
  float acc[J];

  #pragma unroll
  for (int j = 0; j < J; ++j) {
    const int q = lane + j * LANES;   // 0..511
    const int dz = q >> 6;            // /64
    const int rem = q - (dz << 6);
    const int dy = rem >> 3;          // /8
    const int dx = rem - (dy << 3);

    ld[j] = dz;
    lh[j] = dy;
    lw[j] = dx;

    gd[j] = od0 + dz;
    gh[j] = oh0 + dy;
    gw[j] = ow0 + dx;

    valid[j] = oc_valid && (gd[j] < Do) && (gh[j] < Ho) && (gw[j] < Wo);
    acc[j] = bval;
  }

  // Halo origins in input coordinates. Out-of-range halo values are zero-filled.
  const int hd0 = od0 + padding - (K - 1);
  const int hh0 = oh0 + padding - (K - 1);
  const int hw0 = ow0 + padding - (K - 1);

  for (int ic0 = 0; ic0 < Cin; ic0 += IC_CHUNK) {
    // Load the IC_CHUNK x 10 x 10 x 10 input halo for this output tile.
    for (int idx = tid; idx < IC_CHUNK * HD * HH * HW; idx += THREADS) {
      const int pos = idx % (HD * HH * HW);
      const int icc = idx / (HD * HH * HW);

      const int iz = pos / (HH * HW);
      const int rem = pos - iz * (HH * HW);
      const int iy = rem / HW;
      const int ix = rem - iy * HW;

      const int ic = ic0 + icc;
      const int xd = hd0 + iz;
      const int xh = hh0 + iy;
      const int xw = hw0 + ix;

      T v = T(0);
      if (ic < Cin &&
          (unsigned)xd < (unsigned)Din &&
          (unsigned)xh < (unsigned)Hin &&
          (unsigned)xw < (unsigned)Win) {
        v = mX(n, ic, xd, xh, xw);
      }
      sX(icc, iz, iy, ix) = v;
    }

    // Load OC_BLOCK x IC_CHUNK x 27 weights.
    for (int idx = tid; idx < OC_BLOCK * IC_CHUNK * KR; idx += THREADS) {
      const int r = idx % KR;
      const int tmp = idx / KR;
      const int icc = tmp % IC_CHUNK;
      const int occ = tmp / IC_CHUNK;

      const int rd = r / 9;
      const int rem = r - rd * 9;
      const int rh = rem / 3;
      const int rw = rem - rh * 3;

      const int ic = ic0 + icc;
      const int oc_g = oc0 + occ;

      T v = T(0);
      if (ic < Cin && oc_g < Cout) {
        v = mW(ic, oc_g, rd, rh, rw);
      }
      sW(occ, icc, r) = v;
    }

    __syncthreads();

    // Register-block the eight depth outputs. Each thread's J outputs share the
    // same y/x position and overlap along z, so stage the 10-deep input window
    // once and reuse every weight across all eight accumulators.
    if (oc_valid) {
      const int dy = lh[0];
      const int dx = lw[0];
      #pragma unroll
      for (int icc = 0; icc < IC_CHUNK; ++icc) {
        #pragma unroll
        for (int rh = 0; rh < K; ++rh) {
          const int iy = dy + (K - 1) - rh;
          #pragma unroll
          for (int rw = 0; rw < K; ++rw) {
            const int ix = dx + (K - 1) - rw;
            float xv[HD];
            #pragma unroll
            for (int iz = 0; iz < HD; ++iz) {
              xv[iz] = (float)sX(icc, iz, iy, ix);
            }
            #pragma unroll
            for (int rd = 0; rd < K; ++rd) {
              const int r = rd * 9 + rh * 3 + rw;
              const float wv = (float)sW(oc, icc, r);
              #pragma unroll
              for (int j = 0; j < J; ++j) {
                acc[j] += xv[j + (K - 1) - rd] * wv;
              }
            }
          }
        }
      }
    }

    __syncthreads();
  }

  #pragma unroll
  for (int j = 0; j < J; ++j) {
    if (!valid[j]) continue;
    mY(n, ocg, gd[j], gh[j], gw[j]) = static_cast<T>(acc[j]);
  }
}

